contract InvMutTest is Test {
    TimelockController c;
    function setUp() public { c = new TimelockController(0, new address[](0), new address[](0)); }
    function testFuzz_property(bytes32 role) public {
        bytes32 storedAdmin = c.getRoleAdmin(role);
        assertTrue(storedAdmin == 0x00 || storedAdmin == c.PROPOSER_ROLE() || storedAdmin == c.EXECUTOR_ROLE() || storedAdmin == c.TIMELOCK_ADMIN_ROLE());
